static List<Vector2> Clip(List<Vector2> p,Func<Vector2,float> d){var r=new List<Vector2>();if(p.Count<3)return r;var a=p.Last();float da=d(a);foreach(var b in p){float db=d(b);if((da>=0)!=(db>=0))r.Add(Vector2.Lerp(a,b,da/(da-db)));if(db>=0)r.Add(b);a=b;da=db;}return r;}
