class Buffer{public List<Vector3> p=new List<Vector3>();public List<Vector2> uv=new List<Vector2>();public List<Color> color=new List<Color>();public List<int> ids=new List<int>();
public void Triangle(Vector3 a,Vector3 b,Vector3 c,Color tint){int i=p.Count;p.AddRange(new[]{a,b,c});uv.AddRange(new[]{Vector2.zero,Vector2.zero,Vector2.zero});color.AddRange(new[]{tint,tint,tint});ids.AddRange(new[]{i,i+1,i+2});}
public void Pole(Vector3 a,Vector3 b,float radius,Color tint){var dir=(b-a).normalized;var r=Vector3.Cross(dir,Vector3.right).normalized*radius;var u=Vector3.Cross(dir,r).normalized*radius;for(int i=0;i<6;i++){float x=i*Mathf.PI/3,y=(i+1)*Mathf.PI/3;var p0=r*Mathf.Cos(x)+u*Mathf.Sin(x);var p1=r*Mathf.Cos(y)+u*Mathf.Sin(y);Triangle(a+p0,b+p0,b+p1,tint);Triangle(a+p0,b+p1,a+p1,tint);Triangle(a,a+p1,a+p0,tint);Triangle(b,b+p0,b+p1,tint);}}
public Mesh Flag(int nation){var metal=new Color(.48f,.46f,.38f,0);var end=new Vector3(0,2.0f,2.35f);Pole(Vector3.zero,end,.045f,metal);Pole(Vector3.up*.22f,Vector3.down*.22f,.11f,new Color(.12f,.14f,.16f,0));var tip=end+end.normalized*.08f;foreach(var a in new[]{Vector3.up,Vector3.down})for(int i=0;i<4;i++){var b=Quaternion.Euler(0,i*90,0)*Vector3.forward;var c=Quaternion.Euler(0,(i+1)*90,0)*Vector3.forward;Triangle(tip+a*.09f,tip+b*.09f,tip+c*.09f,metal);}
var rect=Target[nation];float aspect=(float)rect.width/rect.height;float width=1.2f,height=width*aspect;var begin=end-end.normalized*width;int start=p.Count;const int columns=6,rows=10;
for(int y=0;y<=rows;y++)for(int x=0;x<=columns;x++){float u=x/(float)columns,v=y/(float)rows;var point=begin+end.normalized*u*width-Vector3.up*v*height;point.x=.06f*Mathf.Sin(u*6.3f+v*2)*v;p.Add(point);uv.Add(new Vector2((rect.x+v*rect.width)/4096f,1-(rect.y+(1-u)*rect.height)/4096f));color.Add(new Color(v,v*.35f,nation*.23f,1));}
for(int y=0;y<rows;y++)for(int x=0;x<columns;x++){int a=start+y*(columns+1)+x,b=a+1,c=a+columns+1,d=c+1;ids.AddRange(new[]{a,b,d,a,d,c});}
